{
  "@context": "https://schema.org",
  "@type": "FAQPage",
  "mainEntity": [
    {
      "@type": "Question",
      "name": "Is Emaar in Lucknow the same company that built the Burj Khalifa?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Emaar India is the Indian arm of Emaar Properties of Dubai, the company that built and owns the Burj Khalifa. Emaar India is a separate Indian company headquartered in Gurugram (Wikipedia: Emaar India); it was called Emaar MGF Land Limited until its joint venture with MGF ended in 2016."
      }
    },
    {
      "@type": "Question",
      "name": "What projects does Emaar have in Lucknow?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Two: the Gomti Greens township, which RERA lists as completed in December 2023, with phases such as Hridayam and Samarth; and Elite Oasis, a 35-floor apartment tower in Gomti Nagar Extension launched in June 2025 and due for completion in November 2029 (RERA record, RERA record)."
      }
    },
    {
      "@type": "Question",
      "name": "What is the price of Emaar Elite Oasis?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "At launch in June 2025, reported prices were about ₹2.75–2.90 crore for 3 BHK and ₹3.87–4.15 crore for 4 BHK (launch announcement, 2 Jun 2025); another report gave ₹2.95 crore as the starting price (Knocksense, 3 Jun 2025). Prices change — ask for the current price list and check the carpet area in the RERA record."
      }
    },
    {
      "@type": "Question",
      "name": "Why is the RERA area smaller than the advertised flat size?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Advertised sizes are usually super (saleable) area, which adds walls, lobbies, lifts and common areas. RERA records carpet area — the usable floor inside your flat. For Elite Oasis, the 3 BHK is advertised at about 2,640 sq ft but its RERA carpet area is 138.775 sq m, about 1,494 sq ft (Knocksense, 3 Jun 2025, RERA record)."
      }
    },
    {
      "@type": "Question",
      "name": "Is Emaar India being sold to Adani?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "In 2025 Emaar held sale talks, including with the Adani Group. In September 2025 Emaar told the Dubai Financial Market it has no plans to divest its stake in its Indian entity and is instead exploring partnerships with large Indian groups (Realty Today, 21 Sep 2025)."
      }
    },
    {
      "@type": "Question",
      "name": "When will Elite Oasis be completed?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "The RERA completion date is 17 November 2029 (RERA record). The foundation was laid on 13 March 2026 (Realty n More, 14 Mar 2026)."
      }
    }
  ]
}
